create function public.cluera_live_billing_cutover(p_operation uuid,p_expected_owner text,p_expected_epoch bigint,p_owner text,p_account_digest text,p_reason text)
returns jsonb language plpgsql security definer set search_path='' set lock_timeout='2s' set statement_timeout='5s' as $$
declare r cluera_live_billing_private.processing_owner;prior cluera_live_billing_private.cutover_audit;before_value jsonb;begin
 if p_operation is null or p_owner is null or p_owner not in ('account','cluera') or p_expected_owner is null or p_expected_epoch is null
 or p_account_digest is null or p_account_digest !~ '^[a-f0-9]{64}$' or p_reason is null or length(trim(p_reason)) not between 10 and 500 then return jsonb_build_object('code','INVALID');end if;
 select * into strict r from cluera_live_billing_private.processing_owner where singleton for update;
 select * into prior from cluera_live_billing_private.cutover_audit where operation_id=p_operation;
 if found then
 if prior.before_row->>'owner' is distinct from p_expected_owner or (prior.before_row->>'epoch')::bigint is distinct from p_expected_epoch
 or prior.after_row->>'owner' is distinct from p_owner or prior.after_row->>'account_digest' is distinct from p_account_digest or prior.reason is distinct from trim(p_reason)
 then return jsonb_build_object('code','CONFLICT');end if;return jsonb_build_object('code','APPLIED','epoch',(prior.after_row->>'epoch')::bigint);end if;
 if r.owner<>p_expected_owner or r.epoch<>p_expected_epoch or r.owner=p_owner or (r.account_digest is not null and r.account_digest<>p_account_digest)
 then return jsonb_build_object('code','CONFLICT');end if;
 if false
 or exists(select 1 from cluera_live_billing_private.events where state='PENDING' and lease_until>clock_timestamp())
 then return jsonb_build_object('code','DRAIN_REQUIRED');end if;
 if p_owner='cluera' and (false
 or false
 or false
 -- cancel_future is a local request, not independently confirmed provider
 -- termination; even a failed/REVIEW cancellation may still renew.
 or false
 or false)
 then return jsonb_build_object('code','PADDLE_DRAIN_REQUIRED');end if;
 -- Old Account bindings cannot resolve Cluera revisions or later refunds.
 -- Once any Cluera financial application exists, keep Cluera as owner and
 -- roll back only to another reviewed Cluera runtime, never to the old worker.
 if p_owner='account' and (exists(select 1 from cluera_live_billing_private.intents where state in ('CREATING','BOUND','UNCERTAIN'))
 or exists(select 1 from cluera_live_billing_private.events where state='PENDING')
 or exists(select 1 from cluera_live_billing_private.terms where state in ('ACTIVE','QUEUED','PAUSED'))
 or exists(select 1 from cluera_live_billing_private.subscriptions where state in ('ACTIVE','PAST_DUE','PAUSED'))
 or exists(select 1 from cluera_live_billing_private.payments)
 or exists(select 1 from cluera_live_billing_private.applications))
 then return jsonb_build_object('code','CLUERA_DRAIN_REQUIRED');end if;
 if false
 or exists(select 1 from cluera_live_billing_private.intents where account_digest<>p_account_digest) then return jsonb_build_object('code','CONFLICT');end if;
 before_value:=to_jsonb(r);
 update cluera_live_billing_private.processing_owner set owner=p_owner,epoch=epoch+1,account_digest=p_account_digest,changed_at=clock_timestamp() where singleton returning * into r;
 insert into cluera_live_billing_private.cutover_audit values(p_operation,trim(p_reason),before_value,to_jsonb(r),clock_timestamp());
 return jsonb_build_object('code','APPLIED','epoch',r.epoch);
end$$;
create function public.cluera_live_billing_catalog() returns jsonb language sql security definer set search_path='' set statement_timeout='5s' as $$
 select coalesce(jsonb_agg(jsonb_build_object('revisionId',r.id,'offerCode',r.offer_code,'name',r.name,'amountPaise',r.amount_paise,'currency',r.currency,
 'allowanceSeconds',r.allowance_seconds,'kind',r.kind,'interval',r.interval_name,'razorpayPlanId',r.razorpay_plan_id,'totalCount',r.total_count,
 'testPlanValidated',exists(select 1 from cluera_live_billing_private.plan_verifications v join cluera_live_billing_private.processing_owner o on o.account_digest=v.account_digest where v.revision_id=r.id),'enabled',h.enabled,'version',r.version)
 order by r.amount_paise),'[]') from cluera_live_billing_private.catalog_heads h join cluera_live_billing_private.catalog_revisions r on r.id=h.revision_id
$$;
create function public.cluera_live_billing_admin_read(p_actor uuid,p_session uuid,p_operation uuid default null) returns jsonb
language plpgsql security definer set search_path='' set statement_timeout='5s' as $$declare a cluera_live_billing_private.admin_audit;begin
 if public.account_admin_check(p_actor,p_session,true) is not true then return jsonb_build_object('code','FORBIDDEN');end if;
 if p_operation is null then return jsonb_build_object('code','ACTIVE','catalog',public.cluera_live_billing_catalog());end if;
 select * into a from cluera_live_billing_private.admin_audit where operation_id=p_operation and actor_id=p_actor;
 return case when found then jsonb_build_object('code','APPLIED','revision',a.after_row) else jsonb_build_object('code','NOT_FOUND') end;
end$$;
create function public.cluera_live_billing_admin_mutate(p_actor uuid,p_session uuid,p_operation uuid,p_action text,p_offer text,p_expected_revision uuid,p_reauthenticated_at timestamptz,p_reason text,p_input jsonb)
